func (h dataServiceHandler) closeTransfer(ctx context.Context, _ connect.Spec, stream connect.ServerStream) error {
	var req v2.DataServiceCloseTransferRequest
	if err := stream.Receive(&req); err != nil {
		return err
	}
	res, err := h.svc.CloseTransfer(ctx, &req)
	if err != nil {
		return err
	}
	return stream.Send(res)
}
